
body { 
    margin: 0; 
    font-family: sans-serif; 
    background-color: #f0f0f0; 
    overflow: hidden;
    user-select: none;
}
#app-wrapper {
    width: 100vw;
    height: 100vh;
    overflow: hidden;
    position: relative;
    /* Optional: uncomment if users want rounded corners by default for frameless */
    /* border-radius: 12px; */
    background-color: transparent;
}
/* Resize Handles */
.resize-handle {
    position: absolute;
    z-index: 999999;
}
.resize-handle.top { top: 0; left: 10px; right: 10px; height: 8px; cursor: n-resize; }
.resize-handle.bottom { bottom: 0; left: 10px; right: 10px; height: 8px; cursor: s-resize; }
.resize-handle.left { top: 10px; bottom: 10px; left: 0; width: 8px; cursor: w-resize; }
.resize-handle.right { top: 10px; bottom: 10px; right: 0; width: 8px; cursor: e-resize; }
.resize-handle.top-left { top: 0; left: 0; width: 15px; height: 15px; cursor: nw-resize; }
.resize-handle.top-right { top: 0; right: 0; width: 15px; height: 15px; cursor: ne-resize; }
.resize-handle.bottom-left { bottom: 0; left: 0; width: 15px; height: 15px; cursor: sw-resize; }
.resize-handle.bottom-right { bottom: 0; right: 0; width: 15px; height: 15px; cursor: se-resize; }

/* Draggable Region */
.pythra-window-drag {
    cursor: grab;
}
.pythra-window-drag:active {
    cursor: grabbing;
}

* { 
    box-sizing: border-box; 
}
#root-container, #overlay-container { 
    height: 100vh; 
    width: 100vw; 
    overflow: hidden; 
    position: relative;
}
#overlay-container { 
    position: absolute; 
    top: 0; 
    left: 0; 
    pointer-events: none; 
}
#overlay-container > * { 
    pointer-events: auto; 
}
.custom-widget {
    width: 100%;
    height: 100%;
}
.custom-scrollbar::-webkit-scrollbar {
    display: none; /* for Chrome, Safari, and Opera */
}
.custom-scrollbar {
    -ms-overflow-style: none;  /* for IE and Edge */
    scrollbar-width: none;  /* for Firefox */
}

/* Fix deprecated inset-area warnings by suppressing and using position-area */
* {
    inset-area: unset !important;  /* Remove deprecated inset-area */
}

/* If any elements need positioning, use position-area instead */
[style*="inset-area"] {
    inset-area: unset !important;
    /* Add position-area equivalent if needed */
}

/* Interactive Debug Banner Styles */
#pythra-debug-banner-wrapper {
    position: absolute;
    top: 0;
    right: 0;
    width: 100px;
    height: 100px;
    overflow: visible;
    pointer-events: none;
    z-index: 999999;
}
#pythra-debug-banner {
    position: absolute;
    top: 15px;
    right: -30px;
    width: 120px;
    height: 24px;
    background: linear-gradient(135deg, #ff416c, #ff4b2b);
    color: white;
    font-size: 10px;
    font-weight: bold;
    font-family: sans-serif;
    display: flex;
    align-items: center;
    justify-content: center;
    transform: rotate(45deg);
    box-shadow: 0 2px 5px rgba(0,0,0,0.3);
    cursor: pointer;
    pointer-events: auto;
    transition: all 0.35s cubic-bezier(0.25, 1, 0.5, 1);
    transform-origin: center;
}
#pythra-debug-banner .banner-text {
    letter-spacing: 1px;
}
#pythra-debug-banner .debug-controls {
    display: none;
    align-items: center;
    justify-content: center;
    gap: 8px;
}
#pythra-debug-banner:hover {
    top: 15px;
    right: 15px;
    width: 130px;
    height: 36px;
    transform: rotate(0deg);
    border-radius: 18px;
    background: rgba(15, 15, 20, 0.85);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.15);
    box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.37);
}
#pythra-debug-banner:hover .banner-text {
    display: none;
}
#pythra-debug-banner:hover .debug-controls {
    display: flex;
}
.debug-btn {
    background: transparent;
    border: none;
    color: rgba(255, 255, 255, 0.85);
    cursor: pointer;
    padding: 6px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    transition: all 0.2s ease;
}
.debug-btn:hover {
    background: rgba(255, 255, 255, 0.15);
    color: white;
    transform: scale(1.1);
}
.debug-btn.restart-btn:hover {
    color: #4facfe;
}
.debug-btn.close-btn:hover {
    color: #ff4b2b;
}
.debug-btn.hotreload-btn:hover {
    color: #ffd700;
}

